UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
for (int i = 0; i < garage.variants.Length; i++)
{
    if (garage.specIds[i] != "hdSportsCar") continue;
    garage.Apply(i);
    var v = garage.variants[i];
    sb.AppendLine("variant " + v.root.name);
    sb.AppendLine("  root localRot=" + v.root.transform.localRotation.eulerAngles.ToString("F1") + " localScale=" + v.root.transform.localScale.ToString("F3"));
    foreach (Transform t in v.root.GetComponentsInChildren<Transform>())
    {
        if (t.name.Contains("bonnet") || t.name.Contains("boot") || t.name.Contains("body_sports-car_0"))
        {
            var r = t.GetComponent<Renderer>();
            if (r == null) continue;
            Vector3 c = garage.transform.InverseTransformPoint(r.bounds.center);
            Vector3 e = r.bounds.extents;
            sb.AppendLine("  " + t.name + " parent=" + (t.parent ? t.parent.name : "-")
              + " localRot=" + t.localRotation.eulerAngles.ToString("F1")
              + " worldRot=" + t.rotation.eulerAngles.ToString("F1")
              + " center=" + c.ToString("F2") + " ext=" + e.ToString("F2"));
        }
    }
    break;
}
Debug.Log("PROBE12 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
